import { clsx } from "clsx";
import type { ComponentPropsWithoutRef } from "react";

import "./table.css";

export function Table({ className, ...props }: ComponentPropsWithoutRef<"table">) {
  return <table {...props} className={clsx("mfd-table", className)} />;
}

export function TableCaption({ className, ...props }: ComponentPropsWithoutRef<"caption">) {
  return <caption {...props} className={clsx("mfd-table__caption", className)} />;
}

export function TableHeader({ className, ...props }: ComponentPropsWithoutRef<"thead">) {
  return <thead {...props} className={clsx("mfd-table__header", className)} />;
}

export function TableBody({ className, ...props }: ComponentPropsWithoutRef<"tbody">) {
  return <tbody {...props} className={clsx("mfd-table__body", className)} />;
}

export function TableRow({ className, ...props }: ComponentPropsWithoutRef<"tr">) {
  return <tr {...props} className={clsx("mfd-table__row", className)} />;
}

export function TableHead({ className, scope = "col", ...props }: ComponentPropsWithoutRef<"th">) {
  return <th {...props} className={clsx("mfd-table__head", className)} scope={scope} />;
}

export function TableCell({ className, ...props }: ComponentPropsWithoutRef<"td">) {
  return <td {...props} className={clsx("mfd-table__cell", className)} />;
}

.mfd-table {
  border-collapse: collapse;
  table-layout: fixed;
  width: 100%;
}

.mfd-table__caption {
  color: var(--mfd-color-text-secondary);
  font:
    var(--mfd-typography-caption-font-weight) var(--mfd-typography-caption-font-size) /
    var(--mfd-typography-caption-line-height) var(--mfd-typography-caption-font-family);
  margin-block-end: var(--mfd-space-stack-sm);
  text-align: start;
}

.mfd-table__head,
.mfd-table__cell {
  border-block-end: 1px solid var(--mfd-color-border-subtle);
  overflow-wrap: anywhere;
  padding: var(--mfd-space-stack-sm) var(--mfd-space-inline-md);
  text-align: start;
  vertical-align: middle;
}

.mfd-table__head {
  color: var(--mfd-color-text-secondary);
  font:
    var(--mfd-typography-label-font-weight) var(--mfd-typography-label-font-size) /
    var(--mfd-typography-label-line-height) var(--mfd-typography-label-font-family);
  letter-spacing: var(--mfd-typography-label-letter-spacing);
}

.mfd-table__row {
  min-height: var(--mfd-size-table-row);
}

.mfd-table__body .mfd-table__row:last-child .mfd-table__cell {
  border-block-end: 0;
}
